import numpy as np
from scipy.optimize import curve_fit
from scipy.ndimage import median_filter

d=np.loadtxt('graphene.dat',delimiter='\t',converters={0:lambda s: float(s.replace(',','.')),1:lambda s: float(s.replace(',','.'))})
x,y=d[:,0],d[:,1]
o=np.argsort(x); x,y=x[o],y[o]

def lor(x,x0,gamma,A,off,slope):
    return off + slope*(x-x0) + A*gamma**2/((x-x0)**2+gamma**2)

def lor0(x,x0,gamma,A,off):
    return off + A*gamma**2/((x-x0)**2+gamma**2)

def gau(x,x0,gamma,A,off,slope):
    # gamma here sigma? use HWHM convention: gamma = fwhm/2? For Gaussian use sigma = gamma/sqrt(2ln2) to make gamma HWHM
    sig=gamma/np.sqrt(2*np.log(2))
    return off + slope*(x-x0) + A*np.exp(-(x-x0)**2/(2*sig**2))

def fitwin(lo,hi,func,p0,exclude=None):
    m=(x>=lo)&(x<=hi)
    if exclude is not None:
        m &= ~exclude(x,y)
    xx,yy=x[m],y[m]
    p,cov=curve_fit(func,xx,yy,p0=p0,maxfev=200000,loss='soft_l1',f_scale=300)
    perr=np.sqrt(np.diag(cov))
    return p,perr,m.sum()

print('G fits (lorentzian linear):')
