import numpy as np
from scipy.optimize import curve_fit

d=np.loadtxt('graphene.dat',delimiter='\t',converters={0:lambda s: float(s.replace(',','.')),1:lambda s: float(s.replace(',','.'))})
x,y=d[:,0],d[:,1]
o=np.argsort(x); x,y=x[o],y[o]

def make(order):
    # order = polynomial order of background (0 const, 1 linear, 2 quadratic)
    def f(x,x0,gamma,A,*bg):
        xr=(x-x0)/1000.
        b=sum(c*xr**i for i,c in enumerate(bg))
        return b + A*gamma**2/((x-x0)**2+gamma**2)
    return f

def fit(lo,hi,order,ex=None):
    m=(x>=lo)&(x<=hi)
    if ex is not None: m&=~ex(x,y)
    xx,yy=x[m],y[m]
    p0=[np.median(xx),300,10000]+[np.median(yy)]+[0]*order
    f=make(order)
    p,cov=curve_fit(f,xx,yy,p0=p0,maxfev=500000,method='trf',loss='soft_l1',f_scale=200)
    return p, m.sum()

print('G correct background order')
for order in [0,1,2,3]:
  for lo,hi in [(9000,12000),(9300,11600),(9500,11500),(9800,11200)]:
    p,n=fit(lo,hi,order)
    print(f'ord{order} {lo}-{hi} n{n}: x0={p[0]:.1f} g={p[1]:.1f} A={p[2]:.0f} bg={[round(v,1) for v in p[3:]]}')

print('\n2D correct background order, exclude y>60000')
for order in [0,1,2,3]:
  for lo,hi in [(16800,21200),(17000,21000),(17200,20800),(17500,20500),(16500,21500)]:
    p,n=fit(lo,hi,order,ex=lambda X,Y:Y>60000)
