import numpy as np
from scipy.optimize import curve_fit
d=np.loadtxt('graphene.dat',delimiter='\t',converters={0:lambda s: float(s.replace(',','.')),1:lambda s: float(s.replace(',','.'))})
x,y=d[:,0],d[:,1]
o=np.argsort(x); x,y=x[o],y[o]

def lor(x,x0,g,A,off,sl):
    return off+sl*(x-x0)+A*g*g/((x-x0)**2+g*g)
def gau(x,x0,g,A,off,sl):
    s=g/np.sqrt(2*np.log(2))
    return off+sl*(x-x0)+A*np.exp(-(x-x0)**2/(2*s*s))
def pv(x,x0,g,A,off,sl,eta):
    s=g/np.sqrt(2*np.log(2))
    L=g*g/((x-x0)**2+g*g)
    G=np.exp(-(x-x0)**2/(2*s*s))
    return off+sl*(x-x0)+A*(eta*L+(1-eta)*G)

def fit(lo,hi,func,p0,ex=None):
    m=(x>=lo)&(x<=hi)
    if ex: m&=~ex(x,y)
    xx,yy=x[m],y[m]
    p,c=curve_fit(func,xx,yy,p0=p0,maxfev=500000,method='trf',loss='soft_l1',f_scale=200)
    r=yy-func(xx,*p)
    return p,np.sqrt(np.mean(r*r)),m.sum()

for name,func,p0 in [('lor',lor,[10400,300,10000,10000,1.2]),('gau',gau,[10400,300,10000,10000,1.2]),('pv',pv,[10400,300,10000,10000,1.2,0.5])]:
    p,rmse,n=fit(9300,11600,func,p0)
    print('G',name,'rmse',round(rmse,1),'n',n,'p',[round(v,2) for v in p])
print()
for name,func,p0 in [('lor',lor,[19150,450,60000,12000,-2]),('gau',gau,[19150,450,60000,12000,-2]),('pv',pv,[19150,450,60000,12000,-2,0.5])]:
    p,rmse,n=fit(16800,21200,func,p0,ex=lambda X,Y:Y>70000)
    print('2D',name,'rmse',round(rmse,1),'n',n,'p',[round(v,2) for v in p])
